// HasDocument applies the HasEdge predicate on the "document" edge.
func HasDocument() predicate.ContractExtractionAttempt {
	return predicate.ContractExtractionAttempt(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, DocumentTable, DocumentColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasDocumentWith applies the HasEdge predicate on the "document" edge with a given conditions (other predicates).
func HasDocumentWith(preds ...predicate.ContractSourceDocument) predicate.ContractExtractionAttempt {
	return predicate.ContractExtractionAttempt(func(s *sql.Selector) {
		step := newDocumentStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ContractExtractionAttempt) predicate.ContractExtractionAttempt {
	return predicate.ContractExtractionAttempt(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ContractExtractionAttempt) predicate.ContractExtractionAttempt {
	return predicate.ContractExtractionAttempt(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ContractExtractionAttempt) predicate.ContractExtractionAttempt {
	return predicate.ContractExtractionAttempt(sql.NotPredicates(p))
}
